namespace Umpk.Game.Inventory;

/// <summary>A menu-type registry entry (<c>minecraft:menu</c>): the version-independent facts about a container window kind (the per-version numbering is dataset content). The per-version slot semantics (counts, roles, shift-click ranges) live behind <see cref="ISlotLayoutSource"/> keyed by this type, not on the definition. It is a <see cref="Umpk.Game.Registries.RegistryEntry{T}"/> value like the other definitions and lives in the inventory module because it is inventory-specific.</summary>
/// <param name="LegacyWindowType">The literal window-type string this menu kind is named by in <c>open_screen</c> before 1.14, or null from 1.14 onward, where the packet carries the numeric registry id instead. Pre-1.14 has no menu registry and therefore no wire number at all, so on those versions this string is the only key that means anything and the entry's numeric id is a synthetic index. It equals the entry's identifier for every kind except the horse window, whose wire spelling ("EntityHorse") is not a well-formed identifier and so takes the <c>umpk:</c> namespace as its registry key.</param>
public sealed record MenuTypeDefinition(string? LegacyWindowType = null);
